/* =====================================================================================================
   MANUAL SQL UPGRADE SCRIPT
   Migration: 202609171125117_DropUnreportedCopilotStudioCreditColumns
   =====================================================================================================
   For operators / DBAs who upgrade the Analytics database schema BY HAND instead of running the
   installer (which applies EF migrations automatically). It performs the same schema changes as the
   migration and then stamps __MigrationHistory so EF (DatabaseUpgrader / MigrateDatabaseToLatestVersion)
   and the web app Health page recognise it as applied.

   RUN ORDER
     The manual scripts form a strict prerequisite chain - run them in migration-id order. This one's
     predecessor is 202609171120001_AzureCostTagColumns. If that migration is not already stamped in
     __MigrationHistory this script drops the columns but deliberately does NOT stamp, and tells you so.

   WHAT IT DOES
     Removes four columns from dbo.copilot_studio_credit_daily that Microsoft's Copilot Studio credit API
     does not populate:

       * channel_id         - which channel the agent was used from
       * llm_model          - the model that served the request
       * tool_invoked       - the tool or connector the agent called
       * knowledge_sources  - the knowledge source the answer was grounded on

     A live capture of the per-agent credit response returned a metadata object of exactly ResourceName,
     NonBillableQuantity and Users - none of the four above - and none of them appears in Microsoft's REST
     reference either. They were speculative when the table was created, and in practice every row has
     them NULL. The report offered four pivots, four grid columns and four filters backed by them, all of
     which could only ever answer "Not reported" - which reads as "this tenant did none of that".

   WILL THIS LOSE DATA?
     In practice no: the values are not obtainable from the source API, so the columns are NULL. But this
     IS a DROP COLUMN, and this table has shipped (build 1830, 12 September 2026), so it does exist in
     customer databases. If you want to confirm before running, this returns zero on every deployment
     observed so far:

       SELECT COUNT(*) FROM dbo.copilot_studio_credit_daily
       WHERE channel_id IS NOT NULL OR llm_model IS NOT NULL
          OR tool_invoked IS NOT NULL OR knowledge_sources IS NOT NULL;

     Nothing about money, credits, agents or attribution is affected - these were descriptive dimensions.

   ONE-OFF EFFECT ON THE UPSERT KEY
     These four fields were part of dimension_hash. With them gone the hashed tuple is shorter, so on the
     FIRST import after this upgrade an existing slice is INSERTed under its new hash rather than UPDATEd,
     and settles from the following run onwards. That is one duplicate per slice per day, once - not
     ongoing drift. A deployment whose credit import has never succeeded (the common case, because the
     licensing API refuses application-only callers) has no rows and sees nothing at all.

   RUNTIME
     Instant, at any table size, on every SQL Server edition.

     DROP COLUMN on a column with no index, constraint or default is a metadata-only change: SQL Server
     does not rewrite the table and does not scan it. No maintenance window is required and the importer
     can keep running throughout.

   SAFETY
     * Idempotent: every step is guarded and re-running is a no-op.
     * The stamp is guarded and is reached on the "already applied" path as well, so running this against
       an already-up-to-date database still reconciles __MigrationHistory rather than leaving the
       migration pending.
     * The stamp refuses only if the COLUMNS ARE STILL PRESENT - i.e. the schema work did not complete.
       It never inspects row data. (A data-state guard has broken a customer upgrade before: concurrency
       always beats it, and EF's own installer path does not apply one.)
   ===================================================================================================== */

SET NOCOUNT ON;
GO

/* -----------------------------------------------------------------------------------------------------
   Drop copilot_studio_credit_daily.channel_id   (nvarchar(200))
   ----------------------------------------------------------------------------------------------------- */
IF OBJECT_ID(N'dbo.copilot_studio_credit_daily', N'U') IS NOT NULL
   AND COL_LENGTH(N'dbo.copilot_studio_credit_daily', N'channel_id') IS NOT NULL
BEGIN
    ALTER TABLE [dbo].[copilot_studio_credit_daily] DROP COLUMN [channel_id];
    RAISERROR('DropUnreportedCopilotStudioCreditColumns: dropped copilot_studio_credit_daily.channel_id.', 0, 1) WITH NOWAIT;
END
ELSE
    RAISERROR('DropUnreportedCopilotStudioCreditColumns: copilot_studio_credit_daily.channel_id already absent (or table missing), skipping.', 0, 1) WITH NOWAIT;
GO
/* -----------------------------------------------------------------------------------------------------
   Drop copilot_studio_credit_daily.llm_model   (nvarchar(200))
   ----------------------------------------------------------------------------------------------------- */
IF OBJECT_ID(N'dbo.copilot_studio_credit_daily', N'U') IS NOT NULL
   AND COL_LENGTH(N'dbo.copilot_studio_credit_daily', N'llm_model') IS NOT NULL
BEGIN
    ALTER TABLE [dbo].[copilot_studio_credit_daily] DROP COLUMN [llm_model];
    RAISERROR('DropUnreportedCopilotStudioCreditColumns: dropped copilot_studio_credit_daily.llm_model.', 0, 1) WITH NOWAIT;
END
ELSE
    RAISERROR('DropUnreportedCopilotStudioCreditColumns: copilot_studio_credit_daily.llm_model already absent (or table missing), skipping.', 0, 1) WITH NOWAIT;
GO
/* -----------------------------------------------------------------------------------------------------
   Drop copilot_studio_credit_daily.tool_invoked   (nvarchar(400))
   ----------------------------------------------------------------------------------------------------- */
IF OBJECT_ID(N'dbo.copilot_studio_credit_daily', N'U') IS NOT NULL
   AND COL_LENGTH(N'dbo.copilot_studio_credit_daily', N'tool_invoked') IS NOT NULL
BEGIN
    ALTER TABLE [dbo].[copilot_studio_credit_daily] DROP COLUMN [tool_invoked];
    RAISERROR('DropUnreportedCopilotStudioCreditColumns: dropped copilot_studio_credit_daily.tool_invoked.', 0, 1) WITH NOWAIT;
END
ELSE
    RAISERROR('DropUnreportedCopilotStudioCreditColumns: copilot_studio_credit_daily.tool_invoked already absent (or table missing), skipping.', 0, 1) WITH NOWAIT;
GO
/* -----------------------------------------------------------------------------------------------------
   Drop copilot_studio_credit_daily.knowledge_sources   (nvarchar(400))
   ----------------------------------------------------------------------------------------------------- */
IF OBJECT_ID(N'dbo.copilot_studio_credit_daily', N'U') IS NOT NULL
   AND COL_LENGTH(N'dbo.copilot_studio_credit_daily', N'knowledge_sources') IS NOT NULL
BEGIN
    ALTER TABLE [dbo].[copilot_studio_credit_daily] DROP COLUMN [knowledge_sources];
    RAISERROR('DropUnreportedCopilotStudioCreditColumns: dropped copilot_studio_credit_daily.knowledge_sources.', 0, 1) WITH NOWAIT;
END
ELSE
    RAISERROR('DropUnreportedCopilotStudioCreditColumns: copilot_studio_credit_daily.knowledge_sources already absent (or table missing), skipping.', 0, 1) WITH NOWAIT;
GO

/* =====================================================================================================
   Record the migration so EF (DatabaseUpgrader / MigrateDatabaseToLatestVersion) and the web app Health
   page treat it as applied.

   This migration DOES change the EF entity model, so the predecessor's Model blob cannot be reused: EF
   reads the LAST history row's Model as the source for automatic migrations, and a stale blob would make
   it try to re-add these columns. The model snapshot below is the gzipped EDMX from
   202609171125117_DropUnreportedCopilotStudioCreditColumns.resx, emitted in chunks so no
   single line is unreasonably long. Guarded, so re-running is safe.
   ===================================================================================================== */
IF NOT EXISTS (SELECT 1 FROM dbo.__MigrationHistory WHERE MigrationId = N'202609171125117_DropUnreportedCopilotStudioCreditColumns')
BEGIN
    /* ---------------------------------------------------------------------------------------------
       Refuse to stamp unless the schema work above actually completed.

       This script is split into GO batches, and by default sqlcmd/SSMS CONTINUE to the next batch after
       a statement fails - a severity-16 error aborts its own batch, not the script. Without this check
       an interrupted or partially failed run would fall through to the stamp and record the migration
       as applied when it is not, which is worse than the original error: EF would then believe the
       schema is at this version and skip the migration forever.

       This checks SCHEMA ONLY - are the columns gone. It deliberately does not look at row data.
       --------------------------------------------------------------------------------------------- */
    DECLARE @remaining nvarchar(max) = N'';

    IF COL_LENGTH(N'dbo.copilot_studio_credit_daily', N'channel_id') IS NOT NULL
        SET @remaining += N'channel_id; ';
    IF COL_LENGTH(N'dbo.copilot_studio_credit_daily', N'llm_model') IS NOT NULL
        SET @remaining += N'llm_model; ';
    IF COL_LENGTH(N'dbo.copilot_studio_credit_daily', N'tool_invoked') IS NOT NULL
        SET @remaining += N'tool_invoked; ';
    IF COL_LENGTH(N'dbo.copilot_studio_credit_daily', N'knowledge_sources') IS NOT NULL
        SET @remaining += N'knowledge_sources; ';

    IF @remaining <> N''
    BEGIN
        DECLARE @incomplete nvarchar(max) =
            N'DropUnreportedCopilotStudioCreditColumns: NOT stamped - the schema changes did not complete. '
            + N'Still present: ' + @remaining
            + N'Re-run this script (it is guarded and safe to repeat) and check the earlier output for the '
            + N'failure. The migration is deliberately left unstamped so the upgrade can be retried.';
        RAISERROR(@incomplete, 16, 1) WITH NOWAIT;
    END
    ELSE
    IF EXISTS (SELECT 1 FROM dbo.__MigrationHistory WHERE MigrationId = N'202609171120001_AzureCostTagColumns')
    BEGIN
        DECLARE @model varbinary(max);
        SET @model = ;
        SET @model = @model + ;
        SET @model = @model + ;
        SET @model = @model + ;
        SET @model = @model + ;
        SET @model = @model + ;
        SET @model = @model + ;
        SET @model = @model + ;
        SET @model = @model + ;
        SET @model = @model + ;
        SET @model = @model + ;
        SET @model = @model + ;

        INSERT INTO dbo.__MigrationHistory (MigrationId, ContextKey, Model, ProductVersion)
        SELECT N'202609171125117_DropUnreportedCopilotStudioCreditColumns', ContextKey, @model, ProductVersion
        FROM dbo.__MigrationHistory
        WHERE MigrationId = N'202609171120001_AzureCostTagColumns';
        RAISERROR('DropUnreportedCopilotStudioCreditColumns: recorded in __MigrationHistory.', 0, 1) WITH NOWAIT;
    END
    ELSE
    BEGIN
        DECLARE @noPrev nvarchar(max) =
            N'DropUnreportedCopilotStudioCreditColumns: NOT stamped - the predecessor migration '
            + N'202609171120001_AzureCostTagColumns is not recorded in __MigrationHistory. Run the manual '
            + N'scripts in migration-id order, then re-run this one. The drops above have been applied and '
            + N're-running is safe.';
        RAISERROR(@noPrev, 16, 1) WITH NOWAIT;
    END
END
ELSE
    RAISERROR('DropUnreportedCopilotStudioCreditColumns: already recorded in __MigrationHistory, nothing to do.', 0, 1) WITH NOWAIT;
GO
